"use client";
import { useEffect, useState } from "react";
import { useSession } from "next-auth/react";
import { 
  Trash2, Plus, Layout, Loader2, Users, 
  MessageSquare, Activity, X, Eye 
} from "lucide-react";

export default function AdminDashboard() {
  const { data: session } = useSession();
  const [data, setData] = useState<any>(null);
  const [newColumn, setNewColumn] = useState("");
  const [loading, setLoading] = useState(true);
  const [selectedMessage, setSelectedMessage] = useState<any>(null); // Mesaj detayları için

  // VERİLERİ ÇEK
  const refreshData = () => {
    setLoading(true);
    fetch("/api/admin/stats")
      .then((res) => res.json())
      .then((resData) => {
        setData(resData);
        setLoading(false);
      })
      .catch(() => setLoading(false));
  };

  useEffect(() => {
    refreshData();
  }, []);

  // KULLANICI SİL
  const deleteUser = async (id: string) => {
    if (!confirm("⚠️ Bu kullanıcıyı kalıcı olarak silmek istediğine emin misin?")) return;
    const res = await fetch(`/api/admin/users/${id}`, { method: "DELETE" });
    if (res.ok) refreshData();
  };

  // YENİ AŞAMA EKLE (REVIEW / RETRO)
  const addColumn = async () => {
    if (!newColumn) return;
    const res = await fetch("/api/admin/columns", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({ name: newColumn }),
    });
    if (res.ok) {
      alert(`🚀 "${newColumn}" aşaması başarıyla veritabanına eklendi!`);
      setNewColumn("");
    }
  };

  if (loading) return (
    <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4">
      <Loader2 className="w-12 h-12 text-fuchsia-500 animate-spin" />
      <span className="text-teal-400 font-bold tracking-[0.3em] animate-pulse uppercase">Veriler Yükleniyor...</span>
    </div>
  );

  // Veri güvenliği
  const stats = data?.stats || [];
  const messages = data?.messages || [];

  return (
    <div className="space-y-10 pb-20 animate-in fade-in duration-700">
      
      {/* ÜST ÖZET KARTI */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-[#0E153A] p-6 rounded-3xl border border-teal-400/20 flex items-center gap-4">
          <Users className="text-fuchsia-500" size={30} />
          <div>
            <p className="text-xs text-teal-500/50 uppercase font-black">Kullanıcılar</p>
            <p className="text-2xl text-white font-black">{stats.length}</p>
          </div>
        </div>
        <div className="bg-[#0E153A] p-6 rounded-3xl border border-teal-400/20 flex items-center gap-4">
          <MessageSquare className="text-teal-400" size={30} />
          <div>
            <p className="text-xs text-teal-500/50 uppercase font-black">Mesajlar</p>
            <p className="text-2xl text-white font-black">{messages.length}</p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
        
        {/* KULLANICI LİSTESİ */}
        <div className="lg:col-span-2 bg-[#0E153A]/80 border border-teal-400/10 rounded-[2.5rem] overflow-hidden backdrop-blur-xl shadow-2xl">
          <div className="p-6 bg-teal-400/5 border-b border-teal-400/10 text-white font-bold uppercase italic tracking-widest">
            Kullanıcı Yönetimi
          </div>
          <div className="divide-y divide-teal-400/5">
            {stats.map((user: any) => (
              <div key={user.id} className="p-6 flex items-center justify-between hover:bg-white/[0.02] transition-colors group">
                <div className="flex items-center gap-4">
                  <div className="w-10 h-10 rounded-full bg-gradient-to-tr from-fuchsia-600 to-teal-400 flex items-center justify-center font-black text-white">
                    {user.name?.[0] || "U"}
                  </div>
                  <div>
                    <h3 className="text-white font-bold">{user.name}</h3>
                    <p className="text-[10px] text-teal-500/40">{user.email}</p>
                  </div>
                </div>
                <div className="flex items-center gap-4">
                  <span className="text-fuchsia-400 font-black italic">{user.percentage}%</span>
                  <button onClick={() => deleteUser(user.id)} className="p-2 text-red-500 hover:bg-red-500/20 rounded-lg transition-all">
                    <Trash2 size={18} />
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* SAĞ PANEL: SÜREÇ EKLEME & MESAJLAR */}
        <div className="space-y-8">
          {/* SÜREÇ EKLE */}
          <div className="bg-gradient-to-br from-[#0E153A] to-[#1a1f45] border border-fuchsia-500/30 p-6 rounded-[2rem] shadow-xl">
            <h3 className="text-white font-black uppercase text-sm mb-4 flex items-center gap-2 italic">
              <Plus size={18} className="text-fuchsia-500" /> Yeni Aşama Ekle
            </h3>
            <input 
              value={newColumn}
              onChange={(e) => setNewColumn(e.target.value)}
              placeholder="Örn: Review"
              className="w-full bg-black/40 border border-teal-400/10 p-3 rounded-xl text-white outline-none mb-3"
            />
            <button onClick={addColumn} className="w-full bg-fuchsia-600 p-3 rounded-xl text-white font-black uppercase text-xs hover:bg-fuchsia-500 transition-all">
              Veritabanına Gönder
            </button>
          </div>

          {/* MESAJLAR LİSTESİ */}
          <div className="bg-[#0E153A]/50 border border-teal-400/10 rounded-[2rem] p-6 overflow-hidden">
            <h3 className="text-teal-400 font-bold uppercase text-[10px] tracking-widest mb-4">Gelen Mesajlar</h3>
            <div className="space-y-3">
              {messages.map((m: any) => (
                <div 
                  key={m.id} 
                  onClick={() => setSelectedMessage(m)}
                  className="p-4 bg-white/5 border-l-4 border-fuchsia-500 rounded-r-xl cursor-pointer hover:bg-white/10 transition-all group"
                >
                  <p className="text-white font-bold text-xs group-hover:text-fuchsia-400">{m.name}</p>
                  <p className="text-[10px] text-white/40 truncate">{m.message}</p>
                </div>
              ))}
            </div>
          </div>
        </div>
      </div>

      {/* MESAJ OKUMA MODALI */}
      {selectedMessage && (
        <div className="fixed inset-0 bg-black/80 backdrop-blur-md z-[100] flex items-center justify-center p-4 animate-in fade-in zoom-in duration-300">
          <div className="bg-[#0E153A] border border-teal-400/30 w-full max-w-lg rounded-[2.5rem] p-8 shadow-[0_0_50px_rgba(45,212,191,0.1)]">
            <div className="flex justify-between items-start mb-6">
              <div>
                <h2 className="text-fuchsia-400 font-black text-2xl italic uppercase tracking-tighter">{selectedMessage.name}</h2>
                <p className="text-teal-400/50 text-xs">{selectedMessage.email}</p>
              </div>
              <button onClick={() => setSelectedMessage(null)} className="p-2 hover:bg-white/10 rounded-full transition-all">
                <X className="text-white" />
              </button>
            </div>
            <div className="bg-black/20 p-6 rounded-2xl border border-teal-400/5 max-h-[300px] overflow-y-auto">
              <p className="text-white/80 leading-relaxed italic">"{selectedMessage.message}"</p>
            </div>
            <p className="text-[10px] text-white/20 mt-6 text-right font-mono">
              Gönderilme Tarihi: {new Date(selectedMessage.createdAt).toLocaleString("tr-TR")}
            </p>
          </div>
        </div>
      )}
    </div>
  );
}